// probe.test.js — RED probe for the brick-bounce defects (run BEFORE the fix).
// Pure logic only: step() + collides(), no DOM. These exact cases will move
// into game/neon.test.js once implemented (TDD).

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { createState, step, collides, ballSpeed } from '../game/neon.js';

// D1 — the symptom: the ball plows head-on through a brick (no bounce at all).
test('D1: head-on brick hit bounces the ball back and kills the brick', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244); // [244,316]x[160,180]
  state.ball = { x: 280, y: 190, r: 7, vx: 0, vy: -260 }; // box [273,287]x[183,197], below the brick
  step(state, 1 / 60);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy > 0, 'ball must bounce down after hitting the bottom face');
  assert.equal(collides(state.ball, brick), false, 'ball must be pushed out of the brick');
});

// D2 — tunneling: a 50ms step at level 7 (40px) is longer than the 34px
// brick+ball thickness: the ball lands fully ABOVE the brick, so a discrete
// check at the end position never sees it.
test('D2: a 40px step at level 7 cannot skip a 34px-thick brick', () => {
  const state = createState(7);
  const brick = state.bricks.find((b) => b.row === 4 && b.x === 244);
  state.ball = { x: 280, y: 190, r: 7, vx: 0, vy: -ballSpeed(7) };
  step(state, 0.05); // moves 40px up: y 190 -> 150, fully above the brick
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy > 0, 'ball must bounce, not tunnel through');
  assert.equal(collides(state.ball, brick), false);
});

// D3 — sticky: a ball starting inside a brick must be pushed OUT, not flipped
// in place (a flip without reposition re-overlaps and re-flips forever).
test('D3: overlapping ball is pushed out of the brick after resolution', () => {
  const state = createState(1);
  state.bricks = [{ x: 90, y: 90, w: 40, h: 20, alive: true, row: 0, points: 50 }];
  const brick = state.bricks[0];
  state.ball = { x: 110, y: 101, r: 7, vx: 0, vy: -100 }; // fully inside [90,130]x[90,110]
  step(state, 1 / 60);
  assert.equal(brick.alive, false);
  assert.equal(collides(state.ball, brick), false, 'ball must be outside the brick after resolution');
  assert.ok(state.ball.vy > 0, 'bounce must push the ball away, not flip it in place');
});

// D4 — seam: the ball (14px wide) overlaps two adjacent bricks (8px gap) at
// once. Two per-brick vy flips cancel out and the ball sails through the seam.
test('D4: seam hit over two bricks bounces exactly once', () => {
  const state = createState(1);
  const left = state.bricks.find((b) => b.row === 4 && b.x === 4);   // [4,76]x[160,180]
