  assert.equal(collides(state.ball, left), false);
  assert.equal(collides(state.ball, right), false);
});

// D5 — face vs side: a horizontal hit must flip vx (not vy) and push the ball
// back out of the left face.
test('D5: side hit flips vx, not vy', () => {
  const state = createState(1);
  state.bricks = [{ x: 90, y: 90, w: 40, h: 20, alive: true, row: 0, points: 50 }];
  const brick = state.bricks[0];
  state.ball = { x: 80, y: 100, r: 7, vx: 600, vy: 0 }; // box [73,87]x[93,107], right edge inside brick y-range
