  assert.ok(state.ball.vx < 0, 'horizontal hit must flip vx');
  assert.equal(state.ball.vy, 0, 'a pure side hit must not touch vy');
  assert.ok(state.ball.x + state.ball.r <= brick.x, 'ball must be pushed left of the brick');
});

// D5b — corner: equal entry times on both axes flip BOTH velocities.
test('D5b: corner hit flips both vx and vy', () => {
  const state = createState(1);
  state.bricks = [{ x: 90, y: 90, w: 40, h: 20, alive: true, row: 0, points: 50 }];
  const brick = state.bricks[0];
  state.ball = { x: 80, y: 130, r: 7, vx: 300, vy: -1300 }; // path grazes the bottom-left corner (90,110)
  step(state, 0.05);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0, 'corner hit must flip vx');
  assert.ok(state.ball.vy > 0, 'corner hit must flip vy');
  assert.equal(collides(state.ball, brick), false);
});

// D6 — paddle tunneling: at dt=0.05 a level-1 ball moves 13px, more than the
// 12px paddle window: the bottom edge jumps from above to below the paddle.
test('D6: a 13px step cannot skip the 12px paddle window', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 440.9, r: 7, vx: 0, vy: ballSpeed(1) }; // bottom edge 447.9, above paddle top 448
  step(state, 0.05); // 13px down -> bottom edge 460.9, below the window
  assert.ok(state.ball.vy < 0, 'ball must bounce off the paddle top');
  assert.ok(state.ball.y + state.ball.r <= 448, 'ball must exit above the paddle');
});

// D7 — angle mort: a dead-center paddle hit gives hit=0 -> vx=0, the ball
// loops vertically forever.
test('D7: dead-center paddle hit keeps a playable |vx|', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 439, r: 7, vx: 0, vy: ballSpeed(1) }; // paddle center x = 320
  step(state, 1 / 60);
  assert.ok(Math.abs(state.ball.vx) >= ballSpeed(1) * 0.15, '|vx| must stay above the playability floor');
});

// D8 — vitesse: the paddle bounce rewrites vx without renormalizing; the
// norm drifts (speed*sqrt(1+0.36*hit^2)) instead of staying at the level speed.
test('D8: paddle rebound preserves the level speed', () => {
  const state = createState(2);
  state.ball = { x: 344, y: 439, r: 7, vx: 0, vy: ballSpeed(2) }; // hit = 0.5
  step(state, 1 / 60);
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(norm - ballSpeed(2)) < 1e-9, `norm ${norm} must equal level speed ${ballSpeed(2)}`);
});

