// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. Used as the discrete fallback in resolveBricks().
export function collides(ball, brick) {

edits.oldText:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {

edits.newText:
// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// How far the ball is pushed beyond a face after a bounce, so that it is
// strictly out of the obstacle at the end of the frame.
const EPS = 1;

// Swept hit of the ball's box (center +- r) against a brick over the segment
// [prev, curr] of the current step. Slab test: the entry/exit times on each
// axis define an overlap interval; a collision is an interval overlap within
// [0, 1]. Returns { tEnter, face } or null, where face is the axis entered
// last ('x' = vertical face, 'y' = horizontal face, 'corner' when equal).
function sweptHit(ball, prev, brick) {
  const vx = ball.x - prev.x;
  const vy = ball.y - prev.y;

  let tEnterX;
  let tExitX;
  if (vx === 0) {
    if (ball.x - ball.r >= brick.x + brick.w || ball.x + ball.r <= brick.x) return null;
    tEnterX = -Infinity;
    tExitX = Infinity;
  } else {
    const t1 = (brick.x - (prev.x + ball.r)) / vx;
    const t2 = (brick.x + brick.w - (prev.x - ball.r)) / vx;
    tEnterX = Math.min(t1, t2);
    tExitX = Math.max(t1, t2);
  }

  let tEnterY;
  let tExitY;
  if (vy === 0) {
    if (ball.y - ball.r >= brick.y + brick.h || ball.y + ball.r <= brick.y) return null;
    tEnterY = -Infinity;
    tExitY = Infinity;
  } else {
    const t1 = (brick.y - (prev.y + ball.r)) / vy;
    const t2 = (brick.y + brick.h - (prev.y - ball.r)) / vy;
    tEnterY = Math.min(t1, t2);
    tExitY = Math.max(t1, t2);
  }

  const tEnter = Math.max(tEnterX, tEnterY);
  const tExit = Math.min(tExitX, tExitY);
  if (tEnter > tExit || tEnter > 1 || tExit < 0) return null;

  let face;
  if (Math.abs(tEnterX - tEnterY) < 1e-9) face = 'corner';
  else if (tEnterX > tEnterY) face = 'x';
  else face = 'y';
  return { tEnter, face };
}

// Pushes the ball out of a brick on the given face(s) and flips the matching
// velocity component(s). face is 'x', 'y' or 'corner'. The sign of the
// velocity tells which face was hit and where the ball came from.
function pushOut(ball, brick, face) {
  if (face === 'x' || face === 'corner') {
    if (ball.vx > 0) {
      ball.x = brick.x - ball.r - EPS; // hit the left face, came from the left
      ball.vx = -ball.vx;
    } else if (ball.vx < 0) {
      ball.x = brick.x + brick.w + ball.r + EPS; // hit the right face
      ball.vx = -ball.vx;
    } else {
      // Stationary on x (degenerate): leave on the nearer side.
      const penLeft = ball.x + ball.r - brick.x;
      const penRight = brick.x + brick.w - (ball.x - ball.r);
      ball.x = penLeft < penRight ? brick.x - ball.r - EPS : brick.x + brick.w + ball.r + EPS;
    }
  }
  if (face === 'y' || face === 'corner') {
    if (ball.vy < 0) {
      ball.y = brick.y + brick.h + ball.r + EPS; // hit the bottom face
      ball.vy = -ball.vy;
    } else if (ball.vy > 0) {
      ball.y = brick.y - ball.r - EPS; // hit the top face
      ball.vy = -ball.vy;
    } else {
      const penTop = ball.y + ball.r - brick.y;
      const penBottom = brick.y + brick.h - (ball.y - ball.r);
      ball.y = penTop < penBottom ? brick.y - ball.r - EPS : brick.y + brick.h + ball.r + EPS;
    }
  }
}

// Resolves the ball against the bricks for one step: swept detection on the
// segment [ball.px, ball.py] -> [ball.x, ball.y]. One bounce per pass per
// axis: only the bricks sharing the earliest entry time die (a grid seam
// shares a face plane and dies together with a single flip); later hits are
// never reached after the bounce. A discrete fallback then guarantees the
// ball ends the frame outside every brick.
function resolveBricks(state) {
  const { ball, bricks } = state;
  const prev = { x: ball.px, y: ball.py };

  const hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptHit(ball, prev, brick);
    if (hit) hits.push({ brick, ...hit });
  }
  if (hits.length > 0) {
    let earliest = hits[0];
    for (const hit of hits) if (hit.tEnter < earliest.tEnter) earliest = hit;
    for (const hit of hits) {
      if (Math.abs(hit.tEnter - earliest.tEnter) > 1e-9) continue;
      hit.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(hit.brick, state.combo);
    }
    pushOut(ball, earliest.brick, earliest.face);
  }

  // Discrete fallback: whatever the sweep missed, the ball must not stay
  // inside a brick; push it out on the axis of smallest penetration.
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    const penLeft = ball.x + ball.r - brick.x;
    const penRight = brick.x + brick.w - (ball.x - ball.r);
    const penTop = ball.y + ball.r - brick.y;
    const penBottom = brick.y + brick.h - (ball.y - ball.r);
    if (Math.min(penLeft, penRight) <= Math.min(penTop, penBottom)) {
      if (penLeft < penRight) ball.x = brick.x - ball.r - EPS;
      else ball.x = brick.x + brick.w + ball.r + EPS;
    } else {
      if (penTop < penBottom) ball.y = brick.y - ball.r - EPS;
      else ball.y = brick.y + brick.h + ball.r + EPS;
    }
  }
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the ceiling, the paddle and the bricks. Pure logic: no DOM.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember the previous position: swept (continuous) collision detection
  // needs the segment traveled during this step, not just its end point.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: swept test on the ball's bottom edge crossing the paddle top (a
  // discrete containment test lets a fast ball jump the 12px window), with
  // the ball's box overlapping the paddle in x so corner hits bounce too.
  if (
    ball.vy > 0 &&
    ball.py + ball.r <= paddle.y &&
    ball.y + ball.r >= paddle.y &&
    ball.x + ball.r >= paddle.x &&
    ball.x - ball.r <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r - EPS;
    // The rebound angle depends on where the paddle was hit. The direction is
    // renormalized so the speed after the bounce is exactly the level speed.
    const speed = ballSpeed(state.level);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    let dirX = 0.6 * hit;
    // Playability floor: a dead-center hit (hit = 0) must not give vx = 0.
    if (Math.abs(dirX) < 0.2) dirX = (dirX < 0 ? -1 : 1) * 0.2;
    const dirNorm = Math.hypot(dirX, -1);
    ball.vx = (dirX / dirNorm) * speed;
    ball.vy = (-1 / dirNorm) * speed;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks
  resolveBricks(state);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

