// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// How far the ball is pushed beyond a face after a bounce, so that it is
// strictly out of the obstacle at the end of the frame.
const EPS = 1;

// Swept hit of the ball's box (center +- r) against a brick over the segment
// [prev, curr] of the current step. Slab test: the entry/exit times on each
// axis define an overlap interval; a collision is an interval overlap within
// [0, 1]. Returns { tEnter, face } or null, where face is the axis entered
// last ('x' = vertical face, 'y' = horizontal face, 'corner' when equal).
function sweptHit(ball, prev, brick) {
  const vx = ball.x - prev.x;
  const vy = ball.y - prev.y;

  let tEnterX;
  let tExitX;
  if (vx === 0) {
    if (ball.x - ball.r >= brick.x + brick.w || ball.x + ball.r <= brick.x) return null;
    tEnterX = -Infinity;
    tExitX = Infinity;
  } else {
    const t1 = (brick.x - (prev.x + ball.r)) / vx;
    const t2 = (brick.x + brick.w - (prev.x - ball.r)) / vx;
    tEnterX = Math.min(t1, t2);
    tExitX = Math.max(t1, t2);
  }

  let tEnterY;
  let tExitY;
  if (vy === 0) {
    if (ball.y - ball.r >= brick.y + brick.h || ball.y + ball.r <= brick.y) return null;
    tEnterY = -Infinity;
    tExitY = Infinity;
  } else {
    const t1 = (brick.y - (prev.y + ball.r)) / vy;
    const t2 = (brick.y + brick.h - (prev.y - ball.r)) / vy;
    tEnterY = Math.min(t1, t2);
    tExitY = Math.max(t1, t2);
  }

  const tEnter = Math.max(tEnterX, tEnterY);
  const tExit = Math.min(tExitX, tExitY);
  if (tEnter > tExit || tEnter > 1 || tExit < 0) return null;

  let face;
  if (Math.abs(tEnterX - tEnterY) < 1e-9) face = 'corner';
  else if (tEnterX > tEnterY) face = 'x';
  else face = 'y';
  return { tEnter, face };
}

// Pushes the ball out of a brick on the given face(s) and flips the matching
// velocity component(s). face is 'x', 'y' or 'corner'. The sign of the
// velocity tells which face was hit and where the ball came from.
function pushOut(ball, brick, face) {
  if (face === 'x' || face === 'corner') {
    if (ball.vx > 0) {
      ball.x = brick.x - ball.r - EPS; // hit the left face, came from the left
      ball.vx = -ball.vx;
    } else if (ball.vx < 0) {
      ball.x = brick.x + brick.w + ball.r + EPS; // hit the right face
      ball.vx = -ball.vx;
    } else {
      // Stationary on x (degenerate): leave on the nearer side.
      const penLeft = ball.x + ball.r - brick.x;
      const penRight = brick.x + brick.w - (ball.x - ball.r);
      ball.x = penLeft < penRight ? brick.x - ball.r - EPS : brick.x + brick.w + ball.r + EPS;
    }
  }
  if (face === 'y' || face === 'corner') {
    if (ball.vy < 0) {
      ball.y = brick.y + brick.h + ball.r + EPS; // hit the bottom face
      ball.vy = -ball.vy;
    } else if (ball.vy > 0) {
      ball.y = brick.y - ball.r - EPS; // hit the top face
      ball.vy = -ball.vy;
    } else {
      const penTop = ball.y + ball.r - brick.y;
      const penBottom = brick.y + brick.h - (ball.y - ball.r);
      ball.y = penTop < penBottom ? brick.y - ball.r - EPS : brick.y + brick.h + ball.r + EPS;
    }
  }
}

